static List<Row> Rows(params string[] pairs)
{
    var rows = new List<Row>();
    foreach (string pair in pairs)
    {
        string[] parts = pair.Split('|');
        rows.Add(new Row(parts[0], parts[1]));
    }
    return rows;
}
static AuditReport Run(IRowReader reader) => Practice.AuditAsync(reader).GetAwaiter().GetResult();
static int ReadsFor(params string[] pairs)
{
    var reader = new MemoryRows(Rows(pairs));
    Run(reader);
    return reader.Reads;
}
static AuditReport Reference(List<Row> rows, bool duplicatesAccepted)
{
    var seen = new HashSet<string>();
    int accepted = 0, duplicates = 0, invalid = 0;
    foreach (Row row in rows)
    {
        if (row.Id == "" || row.Title == "") invalid++;
        else if (!seen.Add(row.Id)) { if (duplicatesAccepted) accepted++; else duplicates++; }
        else accepted++;
    }
    string status = rows.Count == 0 ? "empty" : duplicates == 0 && invalid == 0 ? "clean" : "review";
    return new AuditReport(status, accepted, duplicates, invalid);
}
static AuditReport Correct(List<Row> rows) => Reference(rows, false);
static AuditReport DuplicatesAccepted(List<Row> rows) => Reference(rows, true);
